import{z as l,x as s,o as A,c as i,q as e,j as t,D as a,d as r,s as n,S as o}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"深度 LOB 模型的泄漏陷阱","description":"","frontmatter":{"title":"深度 LOB 模型的泄漏陷阱","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/deep-lob-leakage.md","filePath":"quant/deep-lob-leakage.md","lastUpdated":1791413859000}'),p={name:"quant/deep-lob-leakage.md"};function d(D,E,h,F,m,_){const B=s("Mermaid");return A(),i("div",null,[E[2]||(E[2]=e('<h1 id="深度-lob-模型的泄漏陷阱" tabindex="-1">深度 LOB 模型的泄漏陷阱 <a class="header-anchor" href="#深度-lob-模型的泄漏陷阱" aria-label="Permalink to &quot;深度 LOB 模型的泄漏陷阱&quot;">​</a></h1><div class="epigraph"><p>限价簿模型的测试准确率一旦高到不像短时噪声该有的样子，应先当作信息集被污染的诊断，而不是当作可交易边际的发现。</p><footer>—— 对照 López de Prado 对金融机器学习泄漏的警告，以及微观结构研究里时间戳与标签对齐的纪律</footer></div><p><a href="/quant/neural-hawkes-orderflow">Neural Hawkes</a> 把训练目标换回似然；方向分类正是泄漏最爱进的那扇门。<a href="/quant/deeplob-cnn-lstm">DeepLOB</a> 与 <a href="/quant/translob-axiallob">TransLOB</a> 在公开基准上可以把短时中点方向的准确率做到远高于随机。一部分增益来自簿里真实存在的短记忆；另一部分来自研究者在构造张量、标签和切分时，把 \\(t\\) 之后才确定的信息写进了 \\(t\\) 的输入或写进了标签定义。后者是泄漏。它不创造可执行的优势，只创造不可复现的论文数字，并诱使后续工作在同一套被污染的协议上「刷新 SOTA」。本篇把深度 LOB 的泄漏当成<strong>给研究者的警告</strong>：说明污染通常从哪几类信息集错误进来、如何用诊断把它揭出来、合法评估应满足什么。它不是一份「怎样把准确率做高」的清单，也不提供把未来消息写进特征的做法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>合法预测要求：窗口 \\(X_t\\) 只含截至 \\(t\\) 已在该账户可见的簿与成交，标签 \\(y_t\\) 的随机性来自 \\(t\\) 之后的路径，且 \\(y_t\\) 不是 \\(X_t\\) 的代数恒等式。违约之后，网络变成一个昂贵的恒等函数或延迟对齐器。深度模型特别危险，不是因为卷积有魔法，而是因为容量足够记住「标准化用了未来均值」「标签与最后一档共享同一次跳动」这类伪规则，并在同一交易日的相邻窗口上重复它们，使验证集也中毒。</p><p>这与截面因子的<a href="/quant/look-ahead-bias">前视</a>同类，但时钟更密：毫秒级时间戳、本地到达与撮合时间的差、快照与逐笔重建的差，都会在「看起来只是预处理」的步骤里注入未来。交叉验证若再打乱事件，泄漏从偶发变成系统性，见<a href="/quant/cv-leakage-finance">金融 CV 泄漏</a>。</p><p><span class="marginnote">术语翻译：信息泄漏（leakage）就是阅卷前把标准答案混进了考卷——模型「答对」的不是规律，是已经看见的答案。数字实例：滑动窗口若长 50 个事件、步长 1 个事件，相邻窗口重合约 98%；按事件随机对半切分，测试集里几乎每个张量都在训练集里有「双胞胎」，99% 的准确率只证明模型会背邻居。</span></p><h3 id="标签与输入共享同一次中点跳动" tabindex="-1">标签与输入共享同一次中点跳动 <a class="header-anchor" href="#标签与输入共享同一次中点跳动" aria-label="Permalink to &quot;标签与输入共享同一次中点跳动&quot;">​</a></h3><p>短时任务常预测「未来 \\(k\\) 步中点相对现在」的符号。若输入窗口的最后一条消息已经是造成该中点变化的那笔主动成交，则 \\(X\\) 与 \\(y\\) 被同一跳连着：模型只需认出「最后一笔是主动买」，不必预测。合法对齐要求标签所使用的价格路径从<strong>窗口结束之后的下一条消息</strong>开始，并且研究者应在诊断中检查：把最后一条消息从输入里拿掉之后，准确率是否崩掉。崩掉并不自动等于泄漏，但若不崩而准确率仍接近确定性，更应怀疑标签定义本身是当前价差的重写。</p><p>另一类是阈值 \\(\\theta\\) 用了未来一段的波动或未来高低点来划分上/平/下，使类别边界含未来信息。\\(\\theta\\) 只能来自 \\(t\\) 之前的规则。</p><p><span class="marginnote">「中点在下一毫秒的方向」在价差为两个 tick、且一方队列只剩残量时，几乎是簿的几何，不是预测。报告准确率而不报告当时价差与队列状态，是把几何当成 alpha。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>时间戳审计。</strong> 每一行样本列出：输入窗口的最后交易所时间、标签区间的起始交易所时间、该行进入训练集还是测试集的日期。二者必须满足最后输入时间严格早于标签起始，且测试日的全部窗口不得与训练日重叠。本地电脑时钟、供应商归一化时间、撮合时间混用时，跨市场或跨网关的样本会把延迟结构学成「领先」。审计应只用单一官方时间源，并删除迟到包，而不是靠模型去「利用」迟到。</p><p><strong>切分。</strong> 按交易日（或按周）切，禁止按事件随机折。同一日内的滑动窗口高度重叠，随机折等于把几乎相同的张量同时放进两边。验证日与测试日之间按标签长度做禁运。超参（\\(k\\)、档位数、阈值、网络宽度）只在验证日选一次。测试日的准确率若用来选掩码类型或选是否双向注意力，测试日已经变成训练日。</p><h3 id="标准化、重建与「干净快照」" tabindex="-1">标准化、重建与「干净快照」 <a class="header-anchor" href="#标准化、重建与「干净快照」" aria-label="Permalink to &quot;标准化、重建与「干净快照」&quot;">​</a></h3><p>全局 z-score、全样本分位数、用含测试日的主成分对档位降维，都会把测试日的深度水平写进训练输入。标准化应冻结在训练日上，或只用窗口内部当时可见的相对中点变换。簿重建若使用「向后填」——用后一条消息修正前一条快照的错序——则前一条快照已经含有后一条的信息。研究应接受实时可得的不完美簿，并把重建规则写成与生产一致的前向规则。这些是审计条目，不是提高分数的开关。</p><p>诊断不必构造任何额外的未来特征。最低限度的一组是：（1）时间置换：将标签区间相对输入整体后移到无法重叠的远期，合法信号应消失；（2）日切置换：打乱交易日标签但保持日内结构，若分数几乎不降，模型学的是日级体制而非短时簿；（3）恒预测基线与 OFI 线性基线：深度模型必须在同一无泄漏协议下比较增量。诊断的目的是揭穿不可信的数字，不是提供另一条可交易规则。</p><p><span class="marginnote">FI-2010 等公共基准的切分被反复调参后，本身会变成一种文献级过拟合。在自有数据上复现时，应预指定切分日历，而不是挑选让 DeepLOB「最像论文」的那一段。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>泄漏抬高准确率的机制很普通：训练损失可以沿伪相关降到接近零，而伪相关在重叠窗口的验证集上重复。深度网络的容量把这一过程自动化。注意力在无因果掩码时尤其直接：未来 token 的键已经含有标签所基于的跳动，softmax 会把质量分给它们，看起来像「学到了长程依赖」。CNN 则可能把窗口末尾几列当成未来的代理，因为滑动构造时末尾列与标签在时间上最近。</p><p>经济上，泄漏的「策略」无法在实盘实现：生产系统看不到测试协议里那些未来标准化常数，也看不到标签对齐时偷偷包含的那次成交。更糟的是，泄漏模型会在研究环境里战胜无泄漏的 OFI 基线，使真正可检验的微观结构事实被扔掉。科学损失大于交易损失——后续论文在同一污染协议上竞赛，领域的可预测性被高估，资金与审稿都被消耗。</p>',21)),(A(),t(o,null,{default:a(()=>[n(B,{id:"mermaid-61",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%9C%AA%E6%9D%A5%E4%BF%A1%E6%81%AF%E6%BA%90%EF%BC%9A%E5%85%B1%E4%BA%AB%E8%B7%B3%E5%8A%A8%20%2F%20%E5%85%A8%E5%B1%80%E7%BB%9F%E8%AE%A1%20%2F%20%E4%BA%8B%E5%90%8E%E9%87%8D%E5%BB%BA%22%5D%20--%3E%20WIN%5B%22%E7%AA%97%E5%8F%A3%E4%B8%8E%E6%A0%87%E7%AD%BE%E8%A2%AB%E5%90%8C%E4%B8%80%E8%B7%B3%E8%BF%9E%E4%BD%8F%22%5D%0A%20%20WIN%20--%3E%20FIT%5B%22%E8%AE%AD%E7%BB%83%E6%8D%9F%E5%A4%B1%E6%B2%BF%E4%BC%AA%E7%9B%B8%E5%85%B3%E4%B8%8B%E9%99%8D%E5%88%B0%E6%8E%A5%E8%BF%91%E9%9B%B6%22%5D%0A%20%20FIT%20--%3E%20OVER%5B%22%E9%AA%8C%E8%AF%81%E7%AA%97%E5%8F%A3%E4%B8%8E%E8%AE%AD%E7%BB%83%E7%AA%97%E5%8F%A3%E9%87%8D%E5%8F%A0%22%5D%0A%20%20OVER%20--%3E%20POISON%5B%22%E4%BC%AA%E7%9B%B8%E5%85%B3%E5%9C%A8%E9%AA%8C%E8%AF%81%E9%9B%86%E9%87%8D%E5%A4%8D%22%5D%0A%20%20POISON%20--%3E%20SOTA%5B%22%E6%A6%9C%E5%8D%95%20SOTA%20%E5%88%B7%E6%96%B0%22%5D%0A%20%20SOTA%20--%3E%20LIVE%5B%22%E5%AE%9E%E7%9B%98%EF%BC%9A%E7%9C%8B%E4%B8%8D%E5%88%B0%E6%9C%AA%E6%9D%A5%E5%B8%B8%E6%95%B0%E4%B8%8E%E9%82%A3%E6%AC%A1%E6%88%90%E4%BA%A4%22%5D%0A%20%20LIVE%20--%3E%20FAIL%5B%22%E4%B8%8D%E5%8F%AF%E5%AE%9E%E7%8E%B0%EF%BC%9A%E7%A0%94%E7%A9%B6%E5%88%86%E9%AB%98%EF%BC%8C%E7%94%9F%E4%BA%A7%E6%97%A0%E8%BE%B9%E9%99%85%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<p><span class="marginnote">直觉类比：因果掩码就是考场上把试卷后面几页遮住——模型读第 \\(t\\) 列时，\\(t\\) 之后的内容在注意力里不可见。没有掩码的注意力像可以偷看后页的考生，它不是更聪明，只是信息更多；而实盘里那些「后页」根本不存在，虚高的长程依赖一上线就消失。</span></p><h3 id="和普通前视、和过拟合的关系" tabindex="-1">和普通前视、和过拟合的关系 <a class="header-anchor" href="#和普通前视、和过拟合的关系" aria-label="Permalink to &quot;和普通前视、和过拟合的关系&quot;">​</a></h3><p>全样本标准化是前视；同一日窗口随机切分是泄漏式 CV；把测试日拿来选 \\(k\\) 是过拟合。三者常一起出现。纠正前视不会自动纠正对基准年份的过拟合。流程应先冻结信息集与切分日历，再谈架构是 CNN 还是 Transformer。架构论文若只改网络、不改协议，其 SOTA 声明对科学无效。</p><p>自身订单出现在历史簿里、却在标签里被当成外生中点，是另一种污染：模型学到「我的单随后价格如何」，这在研究自己的历史时是循环。公共研究应使用不含自己账户的簿，或把自家消息标记为不可用输入。此处只指出循环定义会让开环准确率无意义，不讨论如何在盘中利用未公开信息。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>完全无泄漏的短时预测往往只略高于 OFI 与微观价格等线性摘要。这是可接受的科学结果。把深度模型当成「必须超过 70% 准确率才值得写」的发表压力，是泄漏的激励相容来源。审稿与内部评审应要求：时间线表格、掩码说明、与线性基线的同协议比较、以及诊断（1）（2）的结果。缺一项，准确率表可以视为未完成。</p><p>延迟研究（自己看到簿的时间晚于撮合）会降低合法可预测性，这是诚实的。用供应商的事后完整簿去训、用延迟馈源去测，若未在训练中模拟同一延迟，训练信息集仍比生产更干净，属于乐观偏差。应在训练中施加不优于生产的延迟，而不是在测试中「稍微」加点延迟当稳健性。</p><p>不要展示如何把未来消息、未来中点或未来成交量编码进通道「以验证模型能学会它们」——容量验证应用合成噪声标签，不应用真实未来市场状态。不要把无掩码、全局标准化、随机切分的分数当作上界以外的任何东西。上界的唯一用途是警告：你的协议最多能虚高到这里。</p><p><span class="marginnote">若一组预处理在关掉网络、改成对窗口最后一列做逻辑回归之后仍然极准，泄漏几乎已经发生在数据管道，而不是发生在深度架构。先修管道，再比较 CNN 与 Transformer。</span></p>',9)),(A(),t(o,null,{default:a(()=>[n(B,{id:"mermaid-89",class:"mermaid",graph:"flowchart%20TD%0A%20%20AUD%5B%22%E6%97%B6%E9%97%B4%E6%88%B3%E4%B8%8E%E6%A0%87%E7%AD%BE%E8%B5%B7%E7%82%B9%E5%AE%A1%E8%AE%A1%22%5D%20--%3E%20OK%5B%22%E8%BE%93%E5%85%A5%E4%B8%A5%E6%A0%BC%E6%97%A9%E4%BA%8E%E6%A0%87%E7%AD%BE%22%5D%0A%20%20OK%20--%3E%20SPLIT%5B%22%E6%8C%89%E6%97%A5%E5%88%87%E5%88%86%20%2B%20%E7%A6%81%E8%BF%90%22%5D%0A%20%20SPLIT%20--%3E%20STD%5B%22%E4%BB%85%E7%94%A8%E8%AE%AD%E7%BB%83%E6%97%A5%E6%88%96%E7%AA%97%E5%8F%A3%E5%86%85%E6%A0%87%E5%87%86%E5%8C%96%22%5D%0A%20%20STD%20--%3E%20MASK%5B%22%E6%97%B6%E9%97%B4%E5%9B%A0%E6%9E%9C%E6%8E%A9%E7%A0%81%20%2F%20%E5%89%8D%E5%90%91%E9%87%8D%E5%BB%BA%22%5D%0A%20%20MASK%20--%3E%20BASE%5B%22%E4%B8%8E%20OFI%20%E7%BA%BF%E6%80%A7%E5%9F%BA%E7%BA%BF%E5%90%8C%E5%8D%8F%E8%AE%AE%22%5D%0A%20%20BASE%20--%3E%20DIAG%5B%22%E6%97%B6%E9%97%B4%E7%BD%AE%E6%8D%A2%E4%B8%8E%E6%97%A5%E6%A0%87%E7%AD%BE%E7%BD%AE%E6%8D%A2%E8%AF%8A%E6%96%AD%22%5D%0A%20%20DIAG%20--%3E%20REP%5B%22%E5%8F%AF%E6%8A%A5%E5%91%8A%E7%9A%84%E6%A0%B7%E6%9C%AC%E5%A4%96%E5%A2%9E%E9%87%8F%22%5D%0A%20%20BAD%5B%22%E6%9C%AA%E6%9D%A5%E7%BB%9F%E8%AE%A1%20%2F%20%E5%85%B1%E4%BA%AB%E8%B7%B3%E5%8A%A8%20%2F%20%E6%89%93%E4%B9%B1%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20FAKE%5B%22%E4%B8%8D%E5%8F%AF%E5%AE%9E%E7%8E%B0%E7%9A%84%E5%87%86%E7%A1%AE%E7%8E%87%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>深度 LOB 的异常高准确率应首先当作泄漏诊断：标签与输入共享跳动、未来标准化、事件级随机切分、窗口内看未来快照，都会污染信息集。</li><li>合法协议要求交易所时间上输入严格早于标签、按日切分与禁运、前向重建、因果掩码，以及与 OFI 等线性基线的同协议比较。</li><li>诊断用时间置换与日标签置换揭穿虚高数字；不提供把未来写进特征的方法。泄漏策略在生产中不可实现，却会带偏整个文献。</li><li>先冻结信息集，再比较架构。管道已经极准时，问题不在 CNN 或注意力。</li><li>出处：López de Prado, <em>Advances in Financial Machine Learning</em>, 2018（泄漏、清洗与禁运）；时间对齐纪律与 DeepLOB 设定见 Zhang, Zohren and Roberts, <em>IEEE TSP</em>, 2019，以及 Sirignano, <em>Quantitative Finance</em>, 2019。本篇把后者的任务放进前者的审计框里。</li></ul>',2))])}const C=l(p,[["render",d]]);export{u as __pageData,C as default};
